@log_input_and_output
def validate_counter_sum(partial_res_table, test_res_table, expectation_slot, technology_type, scs=15,
                         pucch_format=None, num_payload_bit=1):
    """
    Validates sum of detected and missed counter in Partial Results Table generated for PUCCH and PRACH performance test
    module. Sum of detected counter and missed counter should be equal to: time_interval * 100 * expected_ul_slots
    e.q. Detected counter = 1, Missed counter = 499, calculated sum = 1 * 100 * 5 = 500.
    Method intentionally ignores first measure as it may be irrelevant.

    :param partial_res_table: Partial results table read from WebUI.
    :type partial_res_table: dict
    :param test_res_table: Test results table read from WebUI.
    :type test_res_table: dict
    :param expectation_slot: Expectation slot used during test model configuration, e.g.: 341
    :type expectation_slot: int or str
    :param technology_type: Technology type of cell used during test model, e.g.: 'TDD' or 'FDD'
    :type technology_type: str
    :param scs: Subcarrier spacing used during test model configuration, e.g.: 15KHz; defaults to 15
    :type scs: int or str
    :param pucch_format: PUCCH format used during test model configuration, e.g.: 'F1', 'F2', 'F3';
                         defaults to None, which means PRACH test model results validation
    :type pucch_format: str or None
    :param num_payload_bit: Number of payload bits used during test model configuration, e.g.: 1, 2, 4; defaults to 1
    :type num_payload_bit: int or str
    :raises MismatchingValue exception if method finds measure that does not sum up.
    """
    rep_time_int = float(test_res_table['Reporting time interval'][0].split(' ')[0])
    log_result("Read reporting time interval value: {0} (in seconds)".format(rep_time_int))

    missed_counters = partial_res_table['Missed counter'][:-1]
    log_result("Read missed counters: {0}".format(missed_counters))

    detected_counters = partial_res_table['Detected counter'][:-1]
    log_result("Read detected counters: {0}".format(detected_counters))

    scs = str(scs).lower().strip('khz').strip()
    log_result(f"Subcarrier spacing used for current configuration: {scs} kHz")

    if technology_type == 'TDD':
        expectation_slot_bits = bin(int(expectation_slot))[-8:].count('1')
        expected_ul_slots = int(scs) * expectation_slot_bits / 60
    elif technology_type == 'FDD':
        expectation_slot_bits = bin(int(expectation_slot)).count('1')
        expected_ul_slots = int(scs) / 15 * expectation_slot_bits
    else:
        raise NoMatchingMethodForValidatingCounters(f"Method does not support {technology_type} technology type for"
                                                    f" validating idle period counter!")

    log_result(f"Number of expectation slot bits: {expectation_slot_bits} (expectation slot: {expectation_slot})")

    if pucch_format == 'F1':
        calculated_counter_sum = int(rep_time_int * 100 * expected_ul_slots * int(num_payload_bit))
    else:
        calculated_counter_sum = int(rep_time_int * 100 * expected_ul_slots)
    log_result(f"Calculated idle period counter sum via equation: {calculated_counter_sum}")

    for i in range(len(missed_counters)):
        log_iteration("Calculating counters for measure number {0}".format(i + 1))
        counter_sum = int(missed_counters[i]) + int(detected_counters[i])

        if calculated_counter_sum != counter_sum:
            raise MismatchingValue("Sum of missed counter ({0}) and detected counter ({1}) is not "
                                   "equal to calculated sum ({2}) for measure number {3}!".
                                   format(missed_counters[i], detected_counters[i], calculated_counter_sum, i + 1))


@log_input_and_output
def validate_false_and_detected_counter(partial_res_table, percentage=3):
    """
    Validates if any of detected and false counter measure exceeds provided threshold,
    according to idle period counter measure. Detected and false counter measure should be smaller
    than percentage * idle period counter, e.g. 3% * 200 = 6. Method intentionally ignores first measure
    as it may be irrelevant.

    :param partial_res_table: Partial results table read from WebUI.
    :type partial_res_table: dict
    :param percentage: Percentage of false and detected counter that may occur in single measure.
    :type percentage: int
    :raises MismatchingValue exception when any of detected or false counter measure exceeds
    provided threshold.
    """
    idle_period_counters = partial_res_table['Idle period counter'][:-1]
    log_result("Read idle period counters: {0}".format(idle_period_counters))

    detected_counters = partial_res_table['Detected counter'][:-1]
    log_result("Read detected counters: {0}".format(detected_counters))

    false_counters = partial_res_table['False counter'][:-1]
    log_result("Read false counters: {0}".format(false_counters))

    threshold = float(percentage) / 100 * int(random.choice(idle_period_counters))
    log_result("Calculated threshold: {0}".format(threshold))

    for i in range(len(idle_period_counters)):

        log_iteration("Validating sum of unwanted counters for measure number {0}".format(i + 1))
        unwanted_counter = float(detected_counters[i]) + float(false_counters[i])
        log_iteration("Sum of detected and false counters: {0}".format(unwanted_counter))

        if unwanted_counter > threshold:
            raise MismatchingValue("Detected ({0}) and false ({1}) counter exceeds threshold ({2}) in "
                                   "measure number {3}!".
                                   format(detected_counters[i], false_counters[i], threshold, i + 1))


@log_input_and_output
def validate_false_and_detected_counter_v3(partial_res_table, test_format, number_of_pucch_symbol, expectation_slot,
                                           reception_slot, percentage=3):
    """
    Validates if any of detected and false counter measure exceeds long term average or is/is not near zero
    (depending on test type and number of PUCCH symbol), according to idle period counter measure. Method
    intentionally ignores first measure as it may be irrelevant.

    :param partial_res_table: Partial results table read from WebUI.
    :type partial_res_table: dict
    :param test_format: Format of test to validate e.g. F0
    :type test_format: str
    :param number_of_pucch_symbol: Number of PUCCH test format that method is validating for, e.g. 1
    :type number_of_pucch_symbol: str/None
    :param expectation_slot: Expectation slot used during test model configuration, e.g.: 341
    :type expectation_slot: int or str
    :param reception_slot: Reception slot used during test model configuration, e.g.: 1023
    :type reception_slot: int or str
    :param percentage: Percentage of false and detected counter that may occur in single measure.
    :type percentage: int
    :raises MismatchingValue exception when any of detected or false counter measure exceeds
    provided threshold.
    """
    idle_period_counters = [float(i) for i in partial_res_table['Idle period counter'][:-1]]
    log_result("Read idle period counters: {0}".format(idle_period_counters))

    detected_counters = [float(i) for i in partial_res_table['Detected counter'][:-1]]
    log_result("Read detected counters: {0}".format(detected_counters))

    false_counters = [float(i) for i in partial_res_table['False counter'][:-1]]
    log_result("Read false counters: {0}".format(false_counters))

    threshold = float(percentage) / 100 * int(random.choice(idle_period_counters))
    log_result("Calculated threshold: {0}".format(threshold))

    method = _get_method_for_validating_counters(test_format, number_of_pucch_symbol)

    if method == 'method 1':
        _validate_counter_with_method_1(detected_counters, threshold, false_counters, idle_period_counters,
                                        expectation_slot, reception_slot)

    elif method == 'method 2':
        _validate_counter_with_method_2(detected_counters, idle_period_counters)


@log_input_and_output
def validate_idle_period_counter(partial_res_table, test_res_table, expectation_slot, reception_slot,
                                 technology_type, scs=15, test_format=None, num_payload_bit=1):
    """
    Validates idle period counter value for every measure read from Partial Results Table on WebUI.
    The expected value is equal to equation below:
    (1 - number of expectation bits / number of reception bits) * time interval * 100 * received ul slots
    Method intentionally ignores first measure as it may be irrelevant.

    :param partial_res_table: Partial results table read from WebUI.
    :type partial_res_table: dict
    :param test_res_table: Test results table read from WebUI.
    :type test_res_table: dict
    :param expectation_slot: expectation slot used during test model configuration, e.g.: 341
    :type expectation_slot: int or str
    :param reception_slot: reception slot used during test model configuration, e.g.: 1023
    :type reception_slot: int or str
    :param technology_type: Technology type of cell used during test model, e.g.: 'TDD' or 'FDD'
    :type technology_type: str
    :param test_format: PUCCH format used during test model configuration, e.g.: 'F1', 'F2', 'F3';
                        defaults to None, which means PRACH test model results validation
    :type test_format: str or None
    :param scs: Subcarrier spacing used during test model configuration, e.g.: 15KHz; defaults to 15
    :type scs: int or str
    :param num_payload_bit: Number of payload bits used during test model configuration, e.g.: 1, 2, 4; defaults to 1
    :type num_payload_bit: int or str
    :raises MismatchingValue exception when any of idle period counter measures is not consist with
    calculations.
    """
    rep_time_int = float(test_res_table['Reporting time interval'][0].split(' ')[0])
    log_result("Read reporting time interval value: {0} (in seconds)".format(rep_time_int))

    expectation_slot_bits = bin(int(expectation_slot)).count('1')
    log_result(f"Number of expectation slot bits: {expectation_slot_bits} (expectation slot: {expectation_slot})")

    scs = str(scs).lower().strip('khz').strip()
    log_result(f"Subcarrier spacing used for current configuration: {scs} kHz")

    reception_slot_bits = bin(int(reception_slot)).count('1')
    log_result(f"Number of reception slot bits: {reception_slot_bits} (reception slot: {reception_slot})")

    if technology_type == 'TDD':
        reception_slot_bits_8lsb = bin(int(reception_slot))[-8:].count('1')
        log_result(f"Number of reception slot bits (8 LBS): {reception_slot_bits_8lsb} (reception slot: "
                   f"{reception_slot})")
        received_ul_slots = int(scs) * reception_slot_bits_8lsb / 60
    elif technology_type == 'FDD':
        received_ul_slots = int(scs) / 15 * reception_slot_bits
    else:
        raise NoMatchingMethodForValidatingCounters(f"Method does not support {technology_type} technology type for"
                                                    f" validating idle period counter!")
    log_result(f"Received UL slots: {received_ul_slots} (reception slot: {reception_slot}, SCS: {scs} and "
               f"{technology_type} technology)")

    if test_format == 'F1':
        calculated_counter = ((1 - expectation_slot_bits / reception_slot_bits) * rep_time_int * 100 * received_ul_slots
                              * int(num_payload_bit))
    else:
        calculated_counter = (1 - expectation_slot_bits / reception_slot_bits) * rep_time_int * 100 * received_ul_slots

    log_result("Calculated counter via equation: {0}".format(calculated_counter))

    idle_period_counters = [float(measure) for measure in partial_res_table['Idle period counter'][:-1]]
    log_result("Read idle period counters: {0}".format(idle_period_counters))

    for i, measure in enumerate(idle_period_counters):
        log_iteration("Comparing value ({0}) of measure number {1}".format(measure, i + 1))

        if not _is_close(calculated_counter, float(measure)):
            raise MismatchingValue("Idle period counter ({0}) in measure number {1} is not equal"
                                   " to calculated counter ({2})".format(measure, i + 1, calculated_counter))


@log_input_and_output
def validate_missed_counter(partial_res_table):
    """
    Validates missed counter number in PRACH performance test models.
    Missed counter should be equal to sum of No Pa counter, Wrong Pa counter and
    Wrong timing counter. Method intentionally ignores first measure as it may be irrelevant.

    :param partial_res_table: Partial results table read from WebUI.
    :type partial_res_table: dict
    :raises MismatchingValue exception if method finds measure that does not sum up.
    """
    missed_counters = partial_res_table['Missed counter'][:-1]
    log_result("Read missed counters: {0}".format(missed_counters))

    wrong_timing_counters = partial_res_table['Wrong timing counter'][:-1]
    log_result("Read wrong timing counters: {0}".format(wrong_timing_counters))

    try:
        wrong_pa_counters = partial_res_table['Wrong Pa counter'][:-1]
    except KeyError:
        wrong_pa_counters = partial_res_table['Wrong PA counter'][:-1]
    log_result("Read wrong pa counters: {0}".format(wrong_pa_counters))

    try:
        no_pa_counters = partial_res_table['No Pa Counter'][:-1]
    except KeyError:
        no_pa_counters = partial_res_table['No PA Counter'][:-1]
    log_result("Read no pa counters: {0}".format(no_pa_counters))

    for i in range(len(missed_counters)):
        log_iteration("Validating sum of counters for measure number {0}".format(i + 1))
        calculated_counter = int(wrong_pa_counters[i]) + int(wrong_timing_counters[i]) + int(no_pa_counters[i])
        log_iteration("Calculated sum: {0} \nExpected sum: {1}".format(calculated_counter, missed_counters[i]))

        if int(missed_counters[i]) != calculated_counter:
            raise MismatchingValue("Missed counter ({0}) is not equal the sum of wrong pa counter ({1}) +"
                                   " wrong timing counter ({2}) + no pa counter ({3}) for measure number {4}!".
                                   format(missed_counters[i], wrong_pa_counters[i], wrong_timing_counters[i],
                                          no_pa_counters[i], i + 1))


@log_input_and_output
def validate_pusch_blocks(partial_res_table, test_res_table, ul_slots=10):
    """
    Validates unreceived, defective and received blocks, which sum should be constant in every measure and
    depends on uplink slots, e.g. for 1s we have: 100 (10 ms frames) x UL_slots. Method intentionally
    ignores first measure as it may be irrelevant. Received blocks number should not be higher than
    2% of all bits in measure. As there is some noise in measures due to hw setup, there is some error margin
    in both: validation of constant sums (no more than 20% of all measures may vary) and
    validation with equation (not even single measure may deviate from blocks equation more than
    2%).
    :param partial_res_table: Partial results table read from WebUI.
    :type partial_res_table: dict
    :param test_res_table: Test results table read from WebUI.
    :type test_res_table: dict
    :param ul_slots: Uplink slots per frame on radio where the tests run.
                     For example FDD radios got 10 RX slots per frame.
    :type ul_slots: int/str
    :raises MismatchingValue exception if method finds measure that does not follow equation and exceeds
            error margin.
    :raises ValueError if sum of unreceived, defective and received blocks will not be constant for every measure
            or received blocks number will be higher than 2% of blocks' sum.
    """
    unreceived_blocks = partial_res_table['Unreceived blocks'][:-1]
    log_result("Read unreceived blocks: {0}".format(unreceived_blocks))

    defective_blocks = partial_res_table['Defective blocks'][:-1]
    log_result("Read defective blocks: {0}".format(defective_blocks))

    received_blocks = partial_res_table['Received blocks'][:-1]
    log_result("Read received blocks: {0}".format(received_blocks))

    sum_of_blocks = [int(x) + int(y) + int(z) for (x, y, z) in
                     zip(unreceived_blocks, defective_blocks, received_blocks)]
    log_result("Sums of blocks: {0}".format(sum_of_blocks))

    rep_time_int = int(test_res_table['Reporting time interval'][0].split(' ')[0])
    log_result("Read reporting time interval: {0} (in seconds)".format(rep_time_int))

    _validate_if_sum_of_blocks_are_constant(sum_of_blocks)

    blocks_equation = _validate_blocks_consistency_with_equation(sum_of_blocks, ul_slots, rep_time_int)

    _validate_received_blocks_threshold(received_blocks, blocks_equation)


@log_input_and_output
def validate_pusch_bits(partial_res_table, frc_index):
    """
    Validates unreceived and defective bits at PUSCH performance test module. Sum of unreceived
    bits and defective bits should be constant for every measure. The sum must correspond to the number
    of bits transmitted in the measurement interval. It depends on the FRC index.
    For example: for G-FR1-A3-12 frc index and 1s reporting time interval we have
    400 blocks x 2792 (FRC payload size, as specified in 3GPP 38.141-1/2 appendix A) = 1116800.
    FRC payload size is placed in FRC_PAYLOAD_SIZE dictionary above. By using this method user
    assumes that blocks number in every measure is valid (it might be validated with
    validate_pusch_blocks and is recommended to do it before use of this method).
    As there might occur some noise due to our hardware configuration, test allows 1% error margin
    in measures for sum of blocks (1% deviation from blocks equation).

    :param partial_res_table: Partial results table read from WebUI.
    :type partial_res_table: dict
    :param frc_index: FRC index which measurement reports will be validated.
    :type frc_index: str
    :raises: MismatchingValue exception if sum of unreceived and defective bits is not
             consistent with sum of bits calculated from equation for particular measure.
    """
    unreceived_blocks = partial_res_table['Unreceived blocks'][:-1]
    log_result("Read unreceived blocks: {0}".format(unreceived_blocks))

    defective_blocks = partial_res_table['Defective blocks'][:-1]
    log_result("Read defective blocks: {0}".format(defective_blocks))

    sum_of_blocks = [int(x) + int(y) for (x, y) in zip(unreceived_blocks, defective_blocks)]
    log_result("Calculated sums of blocks: {0}".format(sum_of_blocks))

    unreceived_bits = partial_res_table['Unreceived bits'][:-1]
    log_result("Read unreceived bits: {0}".format(unreceived_bits))

    defective_bits = partial_res_table['Defective bits'][:-1]
    log_result("Read defective bits: {0}".format(defective_bits))

    sum_of_bits = [int(x) + int(y) for (x, y) in zip(unreceived_bits, defective_bits)]
    log_result("Calculated sums of bits: {0}".format(sum_of_bits))

    bits_equation = int(list(set(sum_of_blocks))[0]) * FRC_PAYLOAD_SIZE[frc_index]
    log_result("Expected bits calculated according to equation: {0}".format(bits_equation))

    for i in range(len(sum_of_bits)):
        log_iteration("Validating if sum of bits is between margin for measure number {0}".format(i + 1))

        if not (0.99 * bits_equation <= sum_of_bits[i] <= 1.01 * bits_equation):
            raise MismatchingValue("Sum of unreceived ({0}) and defective ({1}) bits ({2})"
                                   " in measure no. {3} is not consistent with calculated "
                                   " sum of bits from equation ({4}) (with 1% error margin)".
                                   format(unreceived_bits[i], defective_bits[i], sum_of_bits[i], i + 1, bits_equation))

        log_iteration("Sum of bits in measure number {0} sticks to equation.".format(i + 1))


@log_input_and_output
def reformat_performance_test_results(test_type, results):
    """
    Reformats performance test results gotten from admin into previously used selenium one
    :param test_type: one of two supported performance test types, "PUSCH' or "PUCCH'
    :type test_type: str
    :param results: admin performance test results
    :type results: list of dict
    :return: reformatted performance test results and summed performance results
    :rtype: tuple
    """
    if test_type == "PUSCH":
        return _reformat_pusch_performance_test_results(results)
    elif test_type == "PUCCH":
        return _reformat_pucch_performance_test_results(results)
    elif test_type == "PRACH":
        return _reformat_prach_performance_test_results(results)
    else:
        raise UnsupportedTestType("Method does not support '{}' test type".format(test_type))


@log_input_and_output
def create_list_of_table_parameters(param_dict):
    """
    Creates list of parameters based on result table dictionary.
    :param param_dict: performance test result table forwarded as dictionary
    :type param_dict: dict
    :return: list of parameters
    :rtype: list
    """
    return list(param for param in param_dict.keys())


@log_input_and_output
def validate_reporting_time_interval(timestamps, reporting_interval=1, time_format='epoch'):
    """
    Validates whether the test measurement timestamps are with the correct intervals.
    :param timestamps: List of timestamps
    :type timestamps: list
    :param reporting_interval: Expected interval between timestamps, default 1s.
    :type reporting_interval: int
    :param time_format: Format of timestamps, 'epoch'(Unix format e.g. 1728988217) or
                                              'time_str'('HH:MM:SS' e.g '14:30:17'), default 'epoch'
    :type time_format: str
    """
    if time_format == 'time_str':
        timestamps = _convert_time_str_to_epoch(timestamps)

    for i in range(1, len(timestamps)):
        interval = (timestamps[i] - timestamps[i - 1])
        if interval != 1:
            raise ReportingTimeIntervalError(f"Detected incorrect time interval between two measurements [{timestamps[i]}, {timestamps[i - 1]}] "
                                             f"Expected interval: {reporting_interval}, Actual: {interval}")

    log_result("Reporting time intervals are correct.")


@log_input_and_output
def validate_sum_unreceived_defective_blocks_with_ul_slots(results, uplink_slots, measurement_interval,
                                                           blocks_sum_threshold=5):
    """
    Validates unreceived and defective blocks, which sum should be constant in every measure. The sum must correspond to
    the number of uplink slots in the measurement interval. Allowed percentage of incorrect unreceived and defective
    blocks sum values is defined by the threshold parameter.

    Equation
    SumUnreDef = (unreceived[1] + defective[1]) == (unreceived[n] + defective[n])
    AND
    SumUnreDef == frames_per_measurement_interval x NumOfULSlots
    * frames_per_measurement_interval - generally in 1s we have 100 frames (each frame lasts 10 ms)
    * NumOfULSlots - depends on cell technology 4 for TDD, 10 for FDD
    e.g.
    unreceived_blocks = [399, 398], defective_blocks = [1, 2], measurement_interval=1, uplink_slots=4
    SumUnreDef: 399 + 1 == 398 + 2 ... const for every measure
    400 == 100 * 4

    :param results: parsed test results collected via admin API.
    :type results: dict
    :param uplink_slots: Number of uplink slots per frame (4 for TDD, 10 for FDD).
    :type uplink_slots: int or str
    :param measurement_interval: Measurement interval in seconds.
    :type measurement_interval: int or str
    :param blocks_sum_threshold: Maximum allowed percentage of incorrect unreceived and defective sum values, default 5%
    :type blocks_sum_threshold: int
    :raises SumOfParametersNotConstant exception if the sum of parameters is not constant in every measure.
    :raises ValuesNotEqualError  exception if the sum of parameters is not equal to the number of uplink slots
                                 in the measurement interval.
    """
    unreceived_blocks = 'numberOfUnreceivedTransmissionBlocks'
    defective_blocks = 'numberOfDefectiveTransmissionBlocks'

    sum_unre_def = _validate_parameters_sum_is_constant(results, parameter1=unreceived_blocks,
                                                        parameter2=defective_blocks, threshold=blocks_sum_threshold)
    _validate_if_value_equals_ul_slots(value=sum_unre_def, uplink_slots=uplink_slots, interval=measurement_interval)

    log_result("Validation succeeded - sum of unreceived and defective blocks is constant in every measure "
               "and equals to the number of uplink slots in the measurement interval.")


def validate_sum_unreceived_defective_with_transmitted_bits(results, frc_index, bits_sum_threshold=5):
    """
    Validates unreceived and defective bits, which sum should be constant in every measure. The sum must correspond to
    the number of transmitted bits in the measurement interval. Allowed percentage of incorrect unreceived and defective
    bits sum values is defined by the threshold parameter.

    Equation
    SumUnreDef = (unreceived[1] + defective[1]) == (unreceived[n] + defective[n])
    AND
    Transmitted bits = sum(unreceived_block[0] + defective_block[0]) * FRCPayloadSize
    * FRCPayloadSize - value specified in 3GPP 38.141-1/2 appendix A for the direct FRC_index.
      Variable `FRC_PAYLOAD_SIZE` holds the corresponding FRCPayloadSize, which is hardcoded at the top of the file.
    e.g.
    unreceived_bits = [2143392, 2147696], defective_bits = [8608, 4304],
    unreceived_blocks = [996, 998], defective_blocks = [4, 2],
    frc_index='G-FR1-A1-1' = FRC_PAYLOAD_SIZE = 2152

    SumUnreDef: 2152000 = 2143392 + 8608 = 2147696 + 4304
    Transmitted bits: 2152000 == 1000 * 2152

    :param results: parsed test results collected via admin API.
    :type results: dict
    :param frc_index: Test model parameter e.g. 'G-FR1-A1-1'.
    :type frc_index: str
    :param bits_sum_threshold: Maximum allowed percentage of incorrect unreceived and defective sum values, default 5%.
    :type bits_sum_threshold: int
    :raises SumOfParametersNotConstant exception if the sum of parameters is not constant in every measure.
    :raises ValuesNotEqualError exception if the sum of parameters is not equal to the number of uplink slots
                                in the measurement interval.
    """
    unreceived_bits, defective_bits = 'numberOfUnreceivedBits', 'numberOfDefectiveBits'
    unre_blocks, def_blocks = 'numberOfUnreceivedTransmissionBlocks', 'numberOfDefectiveTransmissionBlocks'

    sum_unre_def_bits = _validate_parameters_sum_is_constant(results=results, parameter1=unreceived_bits,
                                                             parameter2=defective_bits, threshold=bits_sum_threshold)

    sums = [v1 + v2 for v1, v2 in zip(results[unre_blocks], results[def_blocks])]
    def_unre_blocks_sum, _ = Counter(sums).most_common(1)[0]

    _validate_if_value_equals_transmitted_bits(value=sum_unre_def_bits, frc_index=frc_index,
                                               sum_def_unre_blocks=def_unre_blocks_sum)

    log_result("Validation succeeded - sum of unreceived and defective bits is constant in every measure "
               "and equals to the number of transmitted bits in the measurement interval.")


@log_input_and_output
def _validate_parameters_sum_is_constant(results, parameter1, parameter2, threshold=5):
    """
    Verifies whether the sum of two parameters remains constant across all measurements.
    The allowed percentage of sum values with an incorrect sum is defined by the threshold parameter.

    :param results: Parsed test results collected via admin API.
    :type results: dict
    :param parameter1: First name of parameter to sum.
    :type parameter1: str
    :param parameter2: Second name of parameter to sum.
    :type parameter2: str
    :param threshold: Maximum allowed percentage of incorrect sum values, default 5%.
    :type threshold: int or str
    :return: Most common sum of parameters across all measurements.
    :rtype: int
    :raises SumOfParametersNotConstant: if the invalid sum of parameters does not exceed the allowed threshold.
    """
    sums = [v1 + v2 for v1, v2 in zip(results[parameter1], results[parameter2])]
    most_common_sum, occurrence_count = Counter(sums).most_common(1)[0]
    invalid_sum_count = len(sums) - occurrence_count
    invalid_sum_percentage = (invalid_sum_count / len(sums)) * 100

    if invalid_sum_percentage > int(threshold):
        raise SumOfParametersNotConstant(f"Sum of '{parameter1}' and '{parameter2}' is not constant across "
                                         f"all measurements and exceeds the threshold: {threshold}% of allowed invalid values.")
    return most_common_sum


@log_input_and_output
def _reformat_pusch_performance_test_results(results):
    """
    Reformats PUSCH performance test results gotten from admin into previously used selenium one
    :param results: admin pusch performance test results
    :type results: list of dict
    :return: reformatted pusch performance test results and summed performance results
    :rtype: tuple
    """
    partial_results = {
        "Detected counter 1": [],
        "Missed counter 1": [],
        "Detected counter 2": [],
        "Missed counter 2": [],
        "Throughput%": [],
        "RSSI": [],
        "Received bits": [],
        "Unreceived bits": [],
        "Defective bits": [],
        "Received blocks": [],
        "Unreceived blocks": [],
        "Defective blocks": [],
    }

    start_ts = results[0]["requestMessage"]["timeReceived"]
    for result in results:
        if result["requestMessage"]["timeReceived"] - start_ts > 15:
            break

        for admin_param_name, formatted_param_name in _params_translate.items():
            partial_results[formatted_param_name].append(result["requestMessage"][admin_param_name])

    cumulative_results = {
        result_name: [sum(result_values)] for result_name, result_values in
        partial_results.items() if result_name not in ["RSSI", "Throughput%"]
    }

    return partial_results, cumulative_results


@log_input_and_output
def _reformat_pucch_performance_test_results(results):
    """
    Reformats PUCCH performance test results gotten from admin into previously used selenium one
    :param results: admin pucch performance test results
    :type results: list of dict
    :return: reformatted pucch performance test results and summed performance results
    :rtype: tuple
    """
    partial_results = {}
    cumulative_results = {}

    time = []
    detected_counters = []
    missed_counters = []
    false_counters = []
    idle_period_counters = []

    for msg in results:
        time_stamp = msg['requestMessage']['timeReceived']
        time.append(str(datetime.fromtimestamp(time_stamp).time()))
        detected_counters.append(msg['requestMessage']['detectedCounter'])
        missed_counters.append(msg['requestMessage']['missedCounter'])
        false_counters.append(msg['requestMessage']['falseCounter'])
        idle_period_counters.append(msg['requestMessage']['idlePeriodCounter'])

    partial_results['Detected counter'] = detected_counters
    partial_results['False counter'] = false_counters
    partial_results['Idle period counter'] = idle_period_counters
    partial_results['Missed counter'] = missed_counters
    partial_results['Time'] = time

    cumulative_results['Detected counter'] = [sum(detected_counters)]
    cumulative_results['False counter'] = [sum(false_counters)]
    cumulative_results['Idle period counter'] = [sum(idle_period_counters)]
    cumulative_results['Missed counter'] = [sum(missed_counters)]

    return partial_results, cumulative_results


@log_input_and_output
def _reformat_prach_performance_test_results(results):
    """
    Reformats PRACH performance test results gotten from admin into previously used selenium one
    :param results: admin prach performance test results
    :type results: list of dict
    :return: reformatted prach performance test results and summed performance results
    :rtype: tuple
    """
    counters = {
        'Detected counter': [],
        'Missed counter': [],
        'False counter': [],
        'Idle period counter': [],
        'No Pa Counter': [],
        'Wrong Pa counter': [],
        'Wrong timing counter': [],
        'Time': []
    }

    for msg in results:
        req_msg = msg['requestMessage']
        counters['Time'].append(str(datetime.fromtimestamp(req_msg['timeReceived']).time()))
        counters['Detected counter'].append(req_msg['detectedCounter'])
        counters['Missed counter'].append(req_msg['missedCounter'])
        counters['False counter'].append(req_msg['falseCounter'])
        counters['Idle period counter'].append(req_msg['idlePeriodCounter'])
        counters['No Pa Counter'].append(req_msg['noPaCounter'])
        counters['Wrong Pa counter'].append(req_msg['wrongPaCounter'])
        counters['Wrong timing counter'].append(req_msg['wrongTimingCounter'])

    cumulative_results = {key: [sum(value)] for key, value in counters.items() if key != 'Time'}

    return counters, cumulative_results


@log_input_and_output
def _validate_received_blocks_threshold(received_blocks, blocks_equation):
    """
    Validates if in any measure received blocks do not exceed 2% threshold as it is restricted in test plan.

    :param received_blocks: Received blocks list for every measure.
    :type received_blocks: list
    :param blocks_equation: Number of blocks calculated from equation.
    :type blocks_equation: int
    :raises: ValueError if received blocks in any measure exceed calculated threshold.
    """
    log_operation("Performing threshold exceeding validation")

    for i, measure in enumerate(received_blocks):
        if int(measure) > blocks_equation * 0.02:
            raise ValueError("Received blocks in measure no. {0} is higher than 2% of sum of blocks!".format(i + 1))

    log_result("All goes well, results are cool!")


@log_input_and_output
def _validate_blocks_consistency_with_equation(sum_of_blocks, ul_slots, rep_time_int):
    """
    Validates if sum of received, unreceived and defective blocks is consent with equation from
    test plan. As there exists some noise in hardware testline configuration we accept that there
    might be some variation in results but we set maximum deviation from equation to 1%.

    :param sum_of_blocks: list with summation of mentioned above blocks for every measure.
    :type sum_of_blocks: list
    :param ul_slots: Uplink slots per frame on radio where the tests run.
    For example FDD radios got 10 RX slots per frame.
    :type ul_slots: int/str
    :param rep_time_int: reporting time interval which may be read from test results table
    :type rep_time_int: int
    :return: correct number of blocks according to equation.
    :raises MismatchingValue exception if there will be any of measure that's sum does not
    follow equation and exceed threshold
    """
    log_operation("Performing validation about consistency with equation")
    blocks_equation = rep_time_int * 100 * int(ul_slots)
    log_result("Calculated blocks equation: {0}".format(blocks_equation))

    for i in range(len(sum_of_blocks)):
        if not (0.98 * blocks_equation < sum_of_blocks[i] < 1.02 * blocks_equation):
            raise MismatchingValue("Measure no. {0} does not follow equation (sum of blocks equals {1},"
                                   " but should be equal to {2} +- 2%).".format(i + 1, sum_of_blocks[i],
                                                                                blocks_equation))

    log_result("All measures stick to equation!")
    return blocks_equation


@log_input_and_output
def _validate_if_sum_of_blocks_are_constant(sum_of_blocks):
    """
    Validates if sum of received, unreceived and defective blocks is constant for every measure.
    As there exists some noise in hardware testline configuration we accept that 20% of all
    measures might not be constant.

    :param sum_of_blocks: sum of blocks for every measure
    :type sum_of_blocks: list
    :raises: ValueError if threshold mentioned above has been exceeded.
    """
    log_operation("Performing validation if sum of blocks of all measures are constant as they should be.")
    measures_count = len(sum_of_blocks)

    if len(set(sum_of_blocks)) > measures_count * 0.20:
        raise ValueError("Sum of unreceived, defective and received blocks is not constant for every measure "
                         "and exceeded noise threshold (there should not be more than 20% of all measures that "
                         "sum of blocks aren't constant)!")

    log_result("Validation succeeded - sum of blocks are constant enough!")


@log_input_and_output
def _set_ack_bits(test_type, pucch_symbol):
    """
    Sets ack bits value according to chosen test_type and pucch_symbol as it may differs for different test module.

    :param test_type: Type of test to get ack bits for,  e.g. F0 or F2. Might be also 'PRACH' which is needed for
                      PRACH performance testing.
    :type test_type: str
    :param pucch_symbol: Number of PUCCH test symbol
    :type pucch_symbol: str
    :return: number of ack bits needed for equation.
    :rtype: int
    :raises NoMatchingAckBitsValue if provided input arguments won't find value for themselves.
    """
    log_operation("Finding out ACK Bits value with input: test_type={0} and pucch_symbol={1}.".format(
        test_type, pucch_symbol))
    if test_type == 'F0' or (test_type == 'F2' and pucch_symbol == '2') or test_type == 'F3' or test_type == 'F4' or \
            test_type == "PRACH":
        return 1
    elif test_type == 'F1':
        return 2
    elif test_type == 'F2' and pucch_symbol == '1':
        return 4
    raise NoMatchingAckBitsValue("Couldn't find proper value of ack bits in equation. "
                                 " Please consider contacting the author of the test if there is some "
                                 " implementation needed.")


@log_input_and_output
def _get_method_for_validating_counters(test_type, number_of_pucch_symbol):
    """
    Gets method for validating counters. Way of validating counters differs for test types and numbers of PUCCH
    symbols as described in QC.
    :param test_type: Type of test to validate e.g. F0
    :type test_type: str
    :param number_of_pucch_symbol: Number of PUCCH test format that method is validating for, e.g. 1
    :type number_of_pucch_symbol: str/None
    :return: method as str
    """
    if test_type == 'F0' or test_type == 'F1' or (test_type == 'F2' and int(number_of_pucch_symbol) == 1):
        return 'method 1'
    elif test_type == 'F3' or test_type == 'F4' or (test_type == 'F2' and int(number_of_pucch_symbol) == 2):
        return 'method 2'
    raise NoMatchingMethodForValidatingCounters("Couldn't find method for validating counters for given test type "
                                                "and number of pucch symbol.")


@log_input_and_output
def _validate_counter_with_method_1(detected_counters, threshold, false_counters, idle_period_counters,
                                    expectation_slot, reception_slot):
    """
    Validates counters: detected counter and false counter (not the sum of them) should vary around a long term
    average value smaller than 1% of idle period counter number (it can be exceeded in a reasonable amount of
    single measurements, expected maximum value < 3%).
    :param detected_counters: detected counters from partial results table read from WebUI
    :param detected_counters: list
    :param threshold: calculated threshold
    :type threshold: float
    :param false_counters: false counters from partial results table read from WebUI
    :type false_counters: list
    :param idle_period_counters: idle period counters from partial results table read from WebUI
    :type idle_period_counters: list
    :param expectation_slot: expectation slot value from test configuration, e.g.: 341
    :type expectation_slot: int or str
    :param reception_slot: reception slot value from test configuration, e.g.: 1023
    :type reception_slot: int or str
    :return: Raises MismatchingValue if detected counters and false counters (not the sum of them) vary around a long
    term average value greater than 1% of idle period counter number or if detected counters or false counters
    exceed 3% of single measurements.
    """
    long_term_avg = 0.01 * sum(idle_period_counters) / len(idle_period_counters)
    log_result("Calculated 1 percentage of long term average: {0}".format(long_term_avg))

    detected_avg = float(sum(detected_counters) / len(detected_counters))
    log_result("Calculated average of detected counters: {0}".format(long_term_avg))

    false_avg = float(sum(false_counters) / len(false_counters))
    log_result("Calculated average of false counters: {0}".format(false_avg))

    if str(expectation_slot) != str(reception_slot):  # if expectation slot equals reception slot, idle counters are 0
        if detected_avg > long_term_avg or false_avg > long_term_avg:
            raise MismatchingValue("Detected ({0}) or false ({1}) counter average exceeds 1% of long term "
                                   "average ({2})".format(detected_avg, false_avg, long_term_avg))
        for i in range(len(idle_period_counters)):
            log_iteration("Validating false and detected counters for measure number {0}".format(i + 1))
            if float(detected_counters[i]) > threshold or float(false_counters[i]) > threshold:
                raise MismatchingValue("Detected ({0}) or false ({1}) counter exceeds threshold ({2}) in "
                                       "measure number {3}!".format(detected_counters[i], false_counters[i],
                                                                    threshold, i + 1))
        else:
            log_warning('Detected and false counter average validation is skipped due to idle counters being 0.')


@log_input_and_output
def _validate_counter_with_method_2(detected_counters, idle_period_counters):
    """
    Validates counters: detected counters should stay zero almost all the time.
    :param detected_counters: detected counters from partial results table read from WebUI
    :param detected_counters: list
    :param idle_period_counters: idle period counters from partial results table read from WebUI
    :type idle_period_counters: list
    :return: Raises MismatchingValue if detected counters are not equal zero more than 75% of the time.
    """
    for i in range(len(idle_period_counters)):
        log_iteration("Validating detected counters for measure number {0}".format(i + 1))
        if len([j for j in detected_counters if j != 0]) > 0.25 * len(detected_counters):
            raise MismatchingValue("Detected counters: {0} should be zero almost all the time.".format(
                                   detected_counters))


@log_input_and_output
def _is_close(a, b, rel_tol=1e-06, abs_tol=1e-06):
    """
    Compares two float numbers taking into account tolerance for inequality.
    :param a: number to be compared
    :type a: float
    :param b: number to be compared
    :type b: float
    :param rel_tol: relative tolerance for inequality between a and b
    :type rel_tol: float
    :param abs_tol: absolute tolerance for inequality between a and b
    :type abs_tol: float
    :return: True if a and b are close to each other, else False
    :rtype: bool
    """
    return abs(a - b) <= max(rel_tol * max(abs(a), abs(b)), abs_tol)


@log_input_and_output
def _validate_if_value_equals_ul_slots(value, uplink_slots, interval):
    """
    Validates if value equals to the number of calculated uplink slots in the measurement interval.
    :param value: Value which will be compared with calculated uplink slots.
    :type value: int or str
    :param uplink_slots: Number of uplink slots per frame.
    :type uplink_slots: int or str
    :param interval: Measurement interval in seconds.
    :type interval: int or str

    Equation of calculating total uplink slots in measurement interval:
    total uplink slots = (interval * 100 total frames per 1s, each frame is 10ms long) * uplink_slots
    """
    total_ul_slots = (int(interval) * 100) * int(uplink_slots)
    if int(value) != total_ul_slots:
        raise ValuesNotEqualError(f"Provided value: {value}, not equal to total uplink slots: {total_ul_slots}")

    log_result(f"Value: {value} is equal to the number of calculated uplink slots {total_ul_slots} in the measurement interval.")


@log_input_and_output
def _validate_if_value_equals_transmitted_bits(value, frc_index, sum_def_unre_blocks):
    """
    Validates if value equals to the number of transmitted bits in the measurement interval.
    Equation:
    Transmitted bits = sum(unreceived_block[0] + defective_block[0]) * FRCPayloadSize
    * FRCPayloadSize - value specified in 3GPP 38.141-1/2 appendix A for the direct frc_index.
      Variable `FRC_PAYLOAD_SIZE` holds the corresponding FRCPayloadSize, which is hardcoded at the top of the file.

    :param value: Value which will be compared with calculated transmitted bits.
    :type value: int or str
    :param frc_index: Test Model parameter e.g. 'G-FR1-A1-1'.
    :type frc_index: str
    :param sum_def_unre_blocks: Sum of defective and unreceived blocks from one measurement.
    :type sum_def_unre_blocks: int or str
    """
    total_transmitted_bits = int(sum_def_unre_blocks) * FRC_PAYLOAD_SIZE[frc_index]
    if int(value) != total_transmitted_bits:
        raise ValuesNotEqualError(f"Provided value: {value}, not equal to total transmitted bits: {total_transmitted_bits}")

    log_result(f"Value: {value} is equal to the number of calculated transmitted bits {total_transmitted_bits} in the measurement interval.")


def _convert_time_str_to_epoch(timestamps):
    """
    Converts timestamps from 'HH:MM:SS' format to Unix format.
    :param timestamps: List of timestamps in 'HH:MM:SS' format
    :type timestamps: list[str]
    :return: List of timestamps in Unix format e.g. [1728988217, 1728988218, 1728988219]
    :rtype: List[int]
    """
    time_format_regex = r'^([01]\d|2[0-3]):[0-5]\d:[0-5]\d$'

    for time_str in timestamps:
        if not re.match(time_format_regex, time_str):
            raise ValueError(f"Invalid time format: {time_str}. Expected 'HH:MM:SS'.")

    today_date = date.today()
    return [int(datetime.combine(today_date, datetime.strptime(t, "%H:%M:%S").time()).timestamp()) for t in timestamps]
